Set-Location "$env:USERPROFILE\dev\IPO_Sniper_AI_v4"

$base64 = ""

$bytes = [System.Convert]::FromBase64String($base64)
$content = [System.Text.Encoding]::UTF8.GetString($bytes)

$path = "app\(app)\workstation\page.tsx"
$backupPath = "app\(app)\workstation\page.tsx.pre-dashboard-ia-backup"

Copy-Item $path $backupPath -Force
Write-Host "Backup saved to $backupPath" -ForegroundColor Yellow

[System.IO.File]::WriteAllText(
    (Resolve-Path $path),
    $content,
    (New-Object System.Text.UTF8Encoding($false))
)

Write-Host "PATCHED: Dashboard shell reorganized." -ForegroundColor Green

Write-Host "`n=== VERIFY: new section headers present ===" -ForegroundColor Cyan
Select-String -Path $path -Pattern "Market Today|Your Market<|IPO Intelligence|Live Intelligence|Supporting Intelligence"

Write-Host "`n=== VERIFY: all 13 panels still present ===" -ForegroundColor Cyan
$panels = @("ResearchTarget", "NewsRail", "MarketContext", "UpcomingEarnings", "WhileYouWereAwayHome", "MarketMoversPanel", "IPOIntelligenceCenter", "ContinueResearchPanel", "LiveIntelligenceFeed", "SystemStatusBar", "WhatMattersNow", "QuantAwarenessStrip", "ResearchSpotlightPlaceholder")
$content2 = Get-Content -LiteralPath $path -Raw
foreach ($p in $panels) {
    $found = $content2.Contains("<$p")
    Write-Host "$p : $found"
}

Write-Host "`n=== TYPE CHECK ===" -ForegroundColor Cyan
npm run type-check